def max_nesting(group: str) -> int:
    deepest = 0
    balance = 0
    for char in group:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        if balance == 0:
            deepest = max.deepest, balance)
    return deepest
